<script setup lang="ts">
import {computed,ref} from 'vue'
import ModelCurve from './ModelCurve.vue'
import StockHistory from './StockHistory.vue'
import type {V3Model} from './v3Types'
const props=defineProps<{model?:V3Model,compact?:boolean}>()
const n=(v:number|null|undefined,d=0)=>v==null?'—':v.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const pct=(v:number|null|undefined)=>v==null?'—':`${v>=0?'+':''}${n(v,2)}%`
const tone=(v:number|null|undefined)=>(v||0)>=0?'gain':'loss'
const journalIndex=ref('')
const record=computed(()=>journalIndex.value?props.model?.journal.find(r=>String(r.revision)===journalIndex.value):props.model?.journal.at(-1))
const validation=computed(()=>props.model?.validation)
const exposure=computed(()=>props.model&&props.model.equity?(props.model.equity-props.model.cash)/props.model.equity*100:0)
const researchSeries=computed(()=>[{key:'v1-100k',label:'V1・10萬元',color:'#2d6c4f',curve:validation.value?.curves.v1||[]},{key:'v3-reference',label:'V3・每日規則回測',color:'#895e9b',curve:validation.value?.curves.v3||[]}])
const liveSeries=computed(()=>[{key:'v3-manual',label:'V3 手動帳戶',color:'#895e9b',curve:props.model?.curve||[]}])
</script>
<template>
<section class="v3-panel">
 <header><div><small>V3 · 手動研究 · 10 萬元</small><h2>主流選股與市場判斷</h2><p>每次你說「更新 V3 持股」，才檢查資料、核對既定計畫並保存新的決策。</p></div><span class="tag">獨立帳戶・試行中</span></header>
 <div class="notice">{{model?.update_policy||'尚未建立帳戶。'}}<br><strong>目前保存日：{{model?.as_of||'—'}} · 決策版本 {{model?.revision??0}}</strong></div>
 <div class="metrics"><article><small>手動帳戶淨值</small><b>NT$ {{n(model?.equity)}}</b><span>初始 100,000 元 · {{pct(model?.portfolio_return_pct)}}</span></article><article><small>現金／持股比例</small><b>NT$ {{n(model?.cash)}}</b><span>持股 {{n(exposure,1)}}% · {{model?.holdings.length||0}} 檔</span></article><article><small>已實現／未實現損益</small><b :class="tone(model?.realized_pnl)">{{n(model?.realized_pnl)}} 元</b><span :class="tone(model?.unrealized_pnl)">未實現 {{n(model?.unrealized_pnl)}} 元</span></article><article><small>手動帳戶完成交易勝率</small><b>{{model?.hit_rate==null?'尚無完成交易':n(model.hit_rate,1)+'%'}}</b><span>{{model?.trades.length||0}} 筆完成 · {{model?.wins||0}} 筆獲利</span></article></div>
 <div v-if="(model?.curve.length||0)>1" class="chart"><h3>手動帳戶紀錄</h3><ModelCurve :series="liveSeries"/></div>
 <p class="help" v-else>帳戶從建立日起計算。下方歷史回測獲利不會放進這個 10 萬元帳戶。</p>
 <template v-if="!compact">
  <div class="section-head"><div><h3>本次市場評估</h3><p>資料截至 {{model?.review?.as_of||'—'}}，不會隨首頁更新而改變。</p></div><span :class="['stance',model?.review?.market.blocked?'defensive':'']">{{model?.review?.market.blocked?'暫停新買進':'可研究買進'}} · 新買入後曝險上限 {{n(model?.review?.target_exposure_pct)}}%</span></div>
  <div class="market" v-if="model?.review"><article v-for="(index,key) in model.review.market.indices" :key="key"><small>{{key==='TAIEX'?'加權指數':'櫃買指數'}}</small><strong>{{n(index.close,2)}}</strong><span>20MA {{n(index.sma20,2)}} · {{index.above?'均線之上':'均線之下'}}</span></article><article><small>站上20MA的普通股比例</small><strong>{{n(model.review.market.breadth_pct,1)}}%</strong><span>分點 {{model.review.market.branch_date}} · RS {{model.review.market.rs_date}}</span></article></div>
  <p class="analysis">{{model?.review?.analysis}}</p><p class="help">{{model?.review?.conclusion}}</p>
  <div class="section-head"><h3>已保存的持股</h3><span>{{model?.as_of}} 評價</span></div>
  <div class="table-wrap"><table><thead><tr><th>股票</th><th>買進日／價格</th><th>股數／成本</th><th>評價價／日期</th><th>已承諾防線</th><th>損益／報酬</th><th>持有論點與失效條件</th></tr></thead><tbody><tr v-for="p in model?.holdings" :key="p.symbol"><td>{{p.name}}<small>{{p.symbol}}</small><StockHistory model-key="v3" :symbol="p.symbol" :as-of="model?.as_of"/></td><td>{{p.entry_date}}<small>{{n(p.entry_price,2)}} 元</small></td><td>{{n(p.qty)}} 股<small>NT$ {{n(p.cost)}}</small></td><td>{{n(p.mark_price,2)}}<small>{{p.mark_date}}</small></td><td>{{n(p.stop,2)}}<small v-if="p.pending_exit">待可成交時退出</small></td><td :class="tone(p.pnl)">{{n(p.pnl)}}<small>{{pct(p.return_pct)}}</small></td><td class="prose">{{p.thesis}}<small>失效：{{p.invalidation}}</small></td></tr><tr v-if="!model?.holdings.length"><td colspan="7" class="empty">目前沒有持股；現金 NT$ {{n(model?.cash)}}。</td></tr></tbody></table></div>
  <div class="section-head"><h3>待核對的買賣計畫</h3><span>模擬計畫，不是券商委託</span></div>
  <div class="table-wrap"><table><thead><tr><th>方向／股票</th><th>訊號日</th><th>最早執行</th><th>預算</th><th>原因</th></tr></thead><tbody><tr v-for="p in model?.pending_orders" :key="p.symbol"><td>{{p.side==='buy'?'買進':'賣出'}} {{p.name}} {{p.symbol}}</td><td>{{p.signal_date}}</td><td>{{p.not_before_date}} 之後的下一交易日</td><td>{{p.budget?n(p.budget)+' 元':'全數退出'}}</td><td class="prose">{{p.reason}}</td></tr><tr v-if="!model?.pending_orders.length"><td colspan="5" class="empty">尚無待執行買賣；請在對話中說「更新 V3 持股」。</td></tr></tbody></table></div>
  <div class="section-head"><h3>研究觀察名單</h3><span>符合量化條件不等於買入指令</span></div>
  <div class="table-wrap"><table><thead><tr><th>股票</th><th>分數</th><th>收盤</th><th>20日淨買占量</th><th>買超持續性</th><th>市場調整強度</th><th>狀態</th></tr></thead><tbody><tr v-for="p in model?.review?.market.candidates" :key="p.symbol"><td>{{p.name}} {{p.symbol}}<StockHistory model-key="v3" :symbol="p.symbol" :as-of="model?.review?.as_of"/></td><td>{{n(p.score,1)}}</td><td>{{n(p.close,2)}}</td><td>{{n(p.pressure_pct,2)}}%</td><td>{{n(p.consistency_pct,1)}}%</td><td>{{pct(p.excess20_pct)}}</td><td>{{p.status}}</td></tr><tr v-if="!model?.review?.market.candidates.length"><td colspan="7" class="empty">本次無符合條件的研究候選。</td></tr></tbody></table></div>
  <details class="details" open><summary>選股、配置與人工研究方式</summary><ol><li>使用 V2 的吸籌、整理轉強與市場調整強度條件，分數至少 80；最多持有 2 檔。</li><li>每檔預算上限為帳戶淨值 50%；另以初始停損距離加成本限制每檔預估風險為淨值 4%。實際金額受現金、手動設定的曝險上限、股價及訊號日成交股數 1% 限制。不是依勝率百分比下注。</li><li>兩個市場指數都低於20MA時不新增。人工研究可降低預算或否決候選；不因排名第一而直接買進。</li><li>每次手動研究檢查產業供需／報價、最新營收與獲利、催化因素及市場是否已反映；保存來源日期、買進論點及失效條件。沒有查證的基本面不當成已確認理由。</li><li>決策後下一交易日開盤試算，開高超過訊號收盤4%則取消。初始防線為3ATR與8%較緊者；最高收盤達買價108%後，手動檢查時改用2ATR。既有持股不重複加碼。</li><li>不追加本金、不借款；盈虧留在帳戶。新股預算依當時淨值重算，既有部位不每天調回等權。</li></ol><p>{{model?.execution_note}}</p></details>
 </template>
 <section v-if="validation" class="validation">
  <div class="section-head"><div><small>歷史規則研究・非手動帳戶實績</small><h3>與 V1 的同本金檢驗</h3><p>{{validation.full.v3.start}} → {{validation.as_of}} · 各投入 100,000 元 · 含未實現及費稅滑價</p></div><span class="tag caution">樣本仍不足</span></div>
  <div class="notice caution">{{validation.conclusion}}</div>
  <div class="table-wrap"><table><thead><tr><th>期間／模型</th><th>總報酬</th><th>勝率</th><th>獲利／完成</th><th>最大回撤</th></tr></thead><tbody><template v-for="(group,label) in {全期回看:validation.full,'5–8月選型':validation.train,'9月起重新起跑':validation.check}" :key="label"><tr v-for="(s,key) in group" :key="label+key"><td>{{label}} · {{key==='v1'?'V1':'V3規則'}}</td><td :class="tone(s.return_pct)">{{pct(s.return_pct)}}</td><td>{{s.hit_rate==null?'—':n(s.hit_rate,1)+'%'}}</td><td>{{s.wins}}／{{s.completed}}</td><td class="loss">{{pct(s.max_drawdown_pct)}}</td></tr></template></tbody></table></div>
  <div v-if="!compact" class="chart"><div class="research-legend"><span><i style="background:#2d6c4f"></i>V1・10萬元</span><span><i style="background:#895e9b"></i>V3・每日規則回測</span><small>左右橫移查看日期；滑鼠移入查看報酬。</small></div><ModelCurve :series="researchSeries"/></div>
  <p class="help">V3 全期勝率的 95% Wilson 區間：{{n(validation.win_rate_ci95[0],1)}}%～{{n(validation.win_rate_ci95[1],1)}}%，仍涵蓋50%以下。</p>
  <details class="details" :open="!compact"><summary>手動更新間隔與成本敏感度</summary><p>以下僅改變固定檢查間隔；預先設定的停損仍每日依行情檢查，兩次決策之間不提高停損線。不代表不規律更新的未來績效。</p><div class="table-wrap"><table><thead><tr><th>情境</th><th>總報酬</th><th>勝率</th><th>完成筆數</th><th>最大回撤</th></tr></thead><tbody><tr v-for="(s,key) in validation.sensitivity" :key="key"><td>{{key==='double_cost'?'每日決策・雙倍成本':`每 ${key} 個交易日決策`}}</td><td :class="tone(s.return_pct)">{{pct(s.return_pct)}}</td><td>{{n(s.hit_rate,1)}}%</td><td>{{s.completed}}</td><td class="loss">{{pct(s.max_drawdown_pct)}}</td></tr></tbody></table></div></details>
  <details class="details"><summary>測試方法、所有變體與資料限制</summary><p>{{validation.selected.criteria}}</p><div class="table-wrap"><table><thead><tr><th>變體</th><th>選型期報酬／勝率</th><th>全期報酬／勝率</th><th>9月重啟報酬</th></tr></thead><tbody><tr v-for="e in validation.experiments" :key="e.config.key"><td>{{e.config.label}}</td><td>{{pct(e.train.return_pct)}}／{{n(e.train.hit_rate,1)}}%</td><td>{{pct(e.full.return_pct)}}／{{n(e.full.hit_rate,1)}}%</td><td>{{pct(e.check.return_pct)}}</td></tr></tbody></table></div><p>{{validation.bootstrap.method}} 勝率 P5 {{n(validation.bootstrap.p5,1)}}%／中位 {{n(validation.bootstrap.median,1)}}%／P95 {{n(validation.bootstrap.p95,1)}}%。</p><ul><li v-for="text in validation.limitations" :key="text">{{text}}</li></ul></details>
  <details v-if="!compact" class="details"><summary>參考觀點與原始來源</summary><p v-for="s in validation.sources" :key="s.url"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title}} ↗</a><br>{{s.idea}}</p></details>
 </section>
 <template v-if="!compact">
 <div class="section-head"><h3>手動決策紀錄</h3><select v-model="journalIndex" aria-label="V3決策紀錄"><option value="">最新紀錄</option><option v-for="r in model?.journal" :key="r.revision" :value="String(r.revision)">{{r.as_of}} · 第 {{r.revision}} 版</option></select></div>
 <div class="analysis" v-if="record"><strong>{{record.recorded_at}} · {{record.kind==='initialize'?'建立帳戶':'手動更新'}}</strong><p>{{record.review.analysis}}</p><p>{{record.review.conclusion}}</p><p>當時淨值 NT$ {{n(record.equity)}} · 現金 NT$ {{n(record.cash)}} · 持股 {{record.holdings.length}} 檔</p><p v-for="a in record.review.actions" :key="a.symbol">{{a.side==='buy'?'買進':'賣出'}} {{a.symbol}} {{a.name}}：{{a.reason}}</p></div>
 <div class="section-head"><h3>已完成的手動帳戶交易</h3></div><div class="table-wrap"><table><thead><tr><th>股票</th><th>買進 → 賣出</th><th>股數</th><th>成本後損益</th><th>報酬</th><th>退出原因</th></tr></thead><tbody><tr v-for="t in model?.trades" :key="t.symbol+t.entry_date"><td>{{t.name}} {{t.symbol}}</td><td>{{t.entry_date}} → {{t.exit_date}}</td><td>{{n(t.qty)}}</td><td :class="tone(t.pnl)">{{n(t.pnl)}}</td><td :class="tone(t.return_pct)">{{pct(t.return_pct)}}</td><td>{{t.exit_reason}}</td></tr><tr v-if="!model?.trades.length"><td class="empty" colspan="6">尚無完成交易。</td></tr></tbody></table></div>
 </template>
 <section v-if="!compact" class="market-study">
  <div class="section-head"><div><small>V3 市場研究 · 手動保存</small><h3>市場位階與下次進場觀察</h3><p>收盤資料截至 {{model?.market_study?.as_of||'—'}}；早上 7:00 後手動更新 V3 選股時同步保存研究。</p></div><span :class="['stance',model?.market_study?.new_buy_allowed?'':'defensive']">{{model?.market_study?.new_buy_allowed?'可研究新買進':'暫停新買進'}}</span></div>
  <template v-if="model?.market_study">
   <p class="analysis">{{model.market_study.analysis}}</p>
   <div class="study-indices"><article v-for="(row,key) in model.market_study.indices" :key="key"><h4>{{key==='TAIEX'?'加權指數':'櫃買指數'}} <span>{{n(row.close,2)}} · 近一日 {{pct(row.change_1d_pct)}}</span></h4><div class="study-levels"><div><small>收盤支撐觀察</small><p v-for="item in row.support" :key="item.basis">{{n(item.value,2)}} <span>{{item.basis}}</span></p><p v-if="!row.support.length">近距離無可確認支撐</p></div><div><small>收盤壓力觀察</small><p v-for="item in row.resistance" :key="item.basis">{{n(item.value,2)}} <span>{{item.basis}}</span></p><p v-if="!row.resistance.length">近距離無可確認壓力</p></div></div><p class="study-trigger">下個交易日若要重站20MA，收盤需至少 {{n(row.next_close_to_sma20,2)}} <small>目前20MA {{n(row.sma20,2)}}；門檻會隨下一根收盤重算</small></p></article></div>
   <div class="study-allocation"><article><small>建議股票比重</small><strong>{{n(model.market_study.allocation.stock_pct)}}%</strong></article><article><small>債券比重</small><strong>{{n(model.market_study.allocation.bond_pct)}}%</strong></article><article><small>保留現金</small><strong>{{n(model.market_study.allocation.cash_pct)}}%</strong></article></div>
   <div class="study-notes"><p><b>下次買入條件：</b>{{model.market_study.buy_condition}}</p><p><b>債券判斷：</b>{{model.market_study.bond_reason}}</p><small>市場廣度 {{n(model.market_study.breadth_pct,1)}}% · 本研究產生於 {{model.market_study.recorded_at.replace('T',' ').slice(0,16)}}。以上配置為當日研究建議，不是帳戶持股或買賣委託。</small></div>
   <details class="details"><summary>位階算法與資料來源</summary><p>{{model.market_study.method}}</p><p v-for="item in model.market_study.sources" :key="item.url"><a :href="item.url" target="_blank" rel="noopener noreferrer">{{item.title}} ↗</a></p></details>
  </template>
  <p v-else class="study-empty">{{model?.market_study_status||'尚未保存市場研究；明確要求產生後，會顯示研究日與位階。現有持股帳本維持原狀。'}}</p>
 </section>
 <footer>V3 手動紀錄與其他模型分開保存。只有實際保存過的決策能列入手動帳戶績效。</footer>
</section>
</template>
